doAssert decimalValidVectors.len == 4096
doAssert decimalInvalidVectors.len == 1024
doAssert hexValidVectors.len == 4096
doAssert hexInvalidVectors.len == 256

for vector in decimalValidVectors:
  var checked = canonicalQuietNaNFloat256
  doAssert tryParseFloat256(vector.text, checked)
  let checkedBits = toBits(checked)
  doAssert checkedBits.word3 == vector.word3
  doAssert checkedBits.word2 == vector.word2
  doAssert checkedBits.word1 == vector.word1
  doAssert checkedBits.word0 == vector.word0

  let raising = parseFloat256(vector.text)
  let raisingBits = toBits(raising)
  doAssert raisingBits.word3 == vector.word3
  doAssert raisingBits.word2 == vector.word2
  doAssert raisingBits.word1 == vector.word1
  doAssert raisingBits.word0 == vector.word0

for text in decimalInvalidVectors:
  var checked = canonicalQuietNaNFloat256
  doAssert not tryParseFloat256(text, checked)
  doAssert sameBits(checked, positiveZeroFloat256)

  var raised = false
  try:
    discard parseFloat256(text)
  except ValueError:
    raised = true
  doAssert raised

for vector in hexValidVectors:
  var parsed = canonicalQuietNaNFloat256
  doAssert tryParseHexFloat256(vector.text, parsed)
  let bits = toBits(parsed)
  doAssert bits.word3 == vector.word3
  doAssert bits.word2 == vector.word2
  doAssert bits.word1 == vector.word1
  doAssert bits.word0 == vector.word0

for text in hexInvalidVectors:
  var parsed = canonicalQuietNaNFloat256
  doAssert not tryParseHexFloat256(text, parsed)
  doAssert sameBits(parsed, positiveZeroFloat256)

echo "F256_PARSING_CONTRACT_OK\t4096\t1024\t4096\t256\t14592\t62"
